import 'package:flutter/material.dart';

/// Counts down from [duration] to zero, one second at a time.
///
/// The object that creates the controller owns it and is responsible for
/// calling [dispose]; a [CountdownTimer] using it will never dispose it.
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  static const Duration _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// The time left before the countdown finishes.
  ///
  /// Starts out at the `duration` the controller was created with.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking down.
  bool get isRunning => _timer != null;

  /// Starts ticking.
  ///
  /// Does nothing when the countdown is already running or has finished.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, (_) => _onTick());
  }

  /// Stops ticking, keeping [remaining] where it is.
  ///
  /// Does nothing when the countdown is not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _cancel();
    notifyListeners();
  }

  /// Stops ticking and puts [remaining] back to the original duration.
  void reset() {
    _cancel();
    _remaining = _duration;
    notifyListeners();
  }

  void _onTick() {
    final Duration next = _remaining - _tick;
    if (next <= Duration.zero) {
      _remaining = Duration.zero;
      _cancel();
    } else {
      _remaining = next;
    }
    notifyListeners();
  }

  void _cancel() {
    _timer?.cancel();
    _timer = null;
  }

  @override
  void dispose() {
    _cancel();
    super.dispose();
  }
}

/// Displays the [controller]'s remaining time and controls for it.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({required this.controller, super.key, this.onFinished});

  /// The countdown to display. Owned by the caller, never disposed here.
  final CountdownController controller;

  /// Called once, when the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  bool _finished = false;

  @override
  void initState() {
    super.initState();
    widget.controller.addListener(_onChanged);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_onChanged);
      widget.controller.addListener(_onChanged);
      _finished = false;
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_onChanged);
    super.dispose();
  }

  void _onChanged() {
    if (!mounted) {
      return;
    }
    setState(() {});
    if (widget.controller.remaining == Duration.zero && !_finished) {
      _finished = true;
      widget.onFinished?.call();
    }
  }

  static String _format(Duration remaining) {
    final int totalSeconds = remaining.inSeconds;
    final String minutes = '${totalSeconds ~/ 60}'.padLeft(2, '0');
    final String seconds = '${totalSeconds % 60}'.padLeft(2, '0');
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    final CountdownController controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(onPressed: controller.start, child: const Text('Start')),
            TextButton(onPressed: controller.pause, child: const Text('Pause')),
            TextButton(onPressed: controller.reset, child: const Text('Reset')),
          ],
        ),
      ],
    );
  }
}

import 'dart:convert';

/// Smallest font size a valid [Settings] may carry.
const int _minFontSize = 8;

/// Largest font size a valid [Settings] may carry.
const int _maxFontSize = 72;

const String _usernameKey = 'username';
const String _fontSizeKey = 'fontSize';
const String _darkModeKey = 'darkMode';
const String _tagsKey = 'tags';

/// Thrown by [parseSettings] when its input cannot be turned into [Settings].
///
/// The [message] always names the offending key when the failure can be
/// attributed to one.
class SettingsFormatException implements Exception {
  /// Creates an exception describing why settings could not be parsed.
  const SettingsFormatException(this.message);

  /// Human readable description of the problem.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// User preferences that can be round-tripped through JSON.
///
/// A valid instance has a non-empty [username], a [fontSize] between
/// [_minFontSize] and [_maxFontSize] inclusive, and only non-empty [tags].
class Settings {
  /// Creates settings for a user.
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
  }) : assert(username != '', 'username must not be empty'),
       assert(
         fontSize >= _minFontSize && fontSize <= _maxFontSize,
         'fontSize must be between $_minFontSize and $_maxFontSize',
       );

  /// Name the settings belong to. Never empty.
  final String username;

  /// Font size in logical pixels, within `$_minFontSize..$_maxFontSize`.
  final int fontSize;

  /// Whether the dark colour scheme is preferred.
  final bool darkMode;

  /// Labels attached to the user. Every entry is non-empty.
  final List<String> tags;

  /// Returns a JSON encodable representation of these settings.
  ///
  /// Feeding [jsonEncode] of the result back into [parseSettings] yields an
  /// equal [Settings].
  Map<String, Object?> toJson() => <String, Object?>{
    _usernameKey: username,
    _fontSizeKey: fontSize,
    _darkModeKey: darkMode,
    _tagsKey: List<String>.unmodifiable(tags),
  };

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        _sameTags(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';
}

/// Parses [json], a JSON document describing a single settings object.
///
/// Throws a [SettingsFormatException] — and nothing else — when the text is
/// not a JSON object, when a required key is missing, or when a value has the
/// wrong type or falls outside its allowed range. Unknown keys are ignored.
Settings parseSettings(String json) {
  final decoded = _decode(json);
  if (decoded is! Map<String, Object?>) {
    throw SettingsFormatException(
      'Expected a JSON object at the top level, but was ${_describe(decoded)}.',
    );
  }
  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded) ?? 14,
    darkMode: _readDarkMode(decoded) ?? false,
    tags: _readTags(decoded) ?? const <String>[],
  );
}

Object? _decode(String source) {
  try {
    return jsonDecode(source) as Object?;
  } on FormatException catch (error) {
    throw SettingsFormatException('Not valid JSON: ${error.message}');
  }
}

String _readUsername(Map<String, Object?> json) {
  if (!json.containsKey(_usernameKey)) {
    throw _missing(_usernameKey);
  }
  final value = json[_usernameKey];
  if (value is! String) {
    _wrongType(_usernameKey, 'a string', value);
  }
  if (value.isEmpty) {
    throw SettingsFormatException('Key "$_usernameKey" must not be empty.');
  }
  return value;
}

int? _readFontSize(Map<String, Object?> json) {
  final value = json[_fontSizeKey];
  if (value == null) {
    if (json.containsKey(_fontSizeKey)) {
      _wrongType(_fontSizeKey, 'an integer', value);
    }
    return null;
  }
  final int fontSize;
  if (value is int) {
    fontSize = value;
  } else if (value is double && value.isFinite && value.truncate() == value) {
    // JSON has a single number type, so 14.0 is an acceptable spelling of 14.
    fontSize = value.toInt();
  } else {
    _wrongType(_fontSizeKey, 'an integer', value);
  }
  if (fontSize < _minFontSize || fontSize > _maxFontSize) {
    throw SettingsFormatException(
      'Key "$_fontSizeKey" must be between $_minFontSize and $_maxFontSize, '
      'but was $fontSize.',
    );
  }
  return fontSize;
}

bool? _readDarkMode(Map<String, Object?> json) {
  final value = json[_darkModeKey];
  if (value == null) {
    if (json.containsKey(_darkModeKey)) {
      _wrongType(_darkModeKey, 'a boolean', value);
    }
    return null;
  }
  if (value is! bool) {
    _wrongType(_darkModeKey, 'a boolean', value);
  }
  return value;
}

List<String>? _readTags(Map<String, Object?> json) {
  final value = json[_tagsKey];
  if (value == null) {
    if (json.containsKey(_tagsKey)) {
      _wrongType(_tagsKey, 'a list of strings', value);
    }
    return null;
  }
  if (value is! List<Object?>) {
    _wrongType(_tagsKey, 'a list of strings', value);
  }
  final tags = <String>[];
  for (final element in value) {
    if (element is! String) {
      _wrongType(_tagsKey, 'a list of strings', element);
    }
    if (element.isEmpty) {
      throw SettingsFormatException(
        'Key "$_tagsKey" must not contain an empty tag.',
      );
    }
    tags.add(element);
  }
  return List<String>.unmodifiable(tags);
}

SettingsFormatException _missing(String key) =>
    SettingsFormatException('Missing required key "$key".');

Never _wrongType(String key, String expected, Object? value) {
  throw SettingsFormatException(
    'Key "$key" must be $expected, but was ${_describe(value)}.',
  );
}

String _describe(Object? value) {
  if (value == null) {
    return 'null';
  }
  if (value is String) {
    return 'a string';
  }
  if (value is bool) {
    return 'a boolean';
  }
  if (value is num) {
    return 'a number';
  }
  if (value is List<Object?>) {
    return 'a list';
  }
  if (value is Map<String, Object?>) {
    return 'an object';
  }
  return 'unsupported';
}

bool _sameTags(List<String> a, List<String> b) {
  if (identical(a, b)) {
    return true;
  }
  if (a.length != b.length) {
    return false;
  }
  for (var i = 0; i < a.length; i++) {
    if (a[i] != b[i]) {
      return false;
    }
  }
  return true;
}

import 'dart:async';

import 'package:flutter/material.dart';

/// One second: both the tick interval and the amount [CountdownController]
/// subtracts from [CountdownController.remaining] on every tick.
const Duration _tick = Duration(seconds: 1);

/// Counts down from a fixed duration to zero, notifying listeners on each tick.
///
/// The controller is owned by whoever creates it: a [CountdownTimer] that is
/// given one will never dispose it, so the same controller can be handed to a
/// new widget after the old one has left the tree.
class CountdownController extends ChangeNotifier {
  /// Creates a controller whose [remaining] starts at [duration].
  CountdownController({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// The time left before the countdown finishes.
  ///
  /// Starts at the duration passed to the constructor and decreases by one
  /// second per tick while running, never going below [Duration.zero].
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking.
  bool get isRunning => _timer != null;

  /// Starts ticking.
  ///
  /// Does nothing while already running or when [remaining] is already zero.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, (Timer timer) => _onTick());
    notifyListeners();
  }

  /// Stops ticking, keeping [remaining] where it is.
  ///
  /// Does nothing when the countdown is not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _cancelTimer();
    notifyListeners();
  }

  /// Stops ticking and puts [remaining] back to the initial duration.
  void reset() {
    _cancelTimer();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _cancelTimer();
    super.dispose();
  }

  void _onTick() {
    if (_remaining <= _tick) {
      _remaining = Duration.zero;
      _cancelTimer();
    } else {
      _remaining -= _tick;
    }
    notifyListeners();
  }

  void _cancelTimer() {
    _timer?.cancel();
    _timer = null;
  }
}

/// Shows the [controller]'s remaining time as `mm:ss` plus start, pause and
/// reset buttons.
///
/// The widget rebuilds on every notification from [controller] and calls
/// [onFinished] once each time the countdown reaches zero. It never disposes
/// [controller].
class CountdownTimer extends StatefulWidget {
  /// Creates a countdown display driven by [controller].
  const CountdownTimer({super.key, required this.controller, this.onFinished});

  /// The countdown to display and drive. Owned by the caller.
  final CountdownController controller;

  /// Called once when the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  /// Whether zero has already been reported through [CountdownTimer.onFinished]
  /// for the current run, so that it is reported exactly once.
  late bool _finished;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining == Duration.zero;
    widget.controller.addListener(_handleControllerChanged);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleControllerChanged);
      _finished = widget.controller.remaining == Duration.zero;
      widget.controller.addListener(_handleControllerChanged);
    }
  }

  @override
  void dispose() {
    // The controller belongs to the caller, so only the listener goes away.
    widget.controller.removeListener(_handleControllerChanged);
    super.dispose();
  }

  void _handleControllerChanged() {
    if (!mounted) {
      return;
    }
    final bool atZero = widget.controller.remaining == Duration.zero;
    final bool justFinished = atZero && !_finished;
    setState(() {
      _finished = atZero;
    });
    if (justFinished) {
      widget.onFinished?.call();
    }
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(widget.controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(
              onPressed: widget.controller.start,
              child: const Text('Start'),
            ),
            TextButton(
              onPressed: widget.controller.pause,
              child: const Text('Pause'),
            ),
            TextButton(
              onPressed: widget.controller.reset,
              child: const Text('Reset'),
            ),
          ],
        ),
      ],
    );
  }

  String _format(Duration value) {
    final String minutes = value.inMinutes.toString().padLeft(2, '0');
    final String seconds = (value.inSeconds % 60).toString().padLeft(2, '0');
    return '$minutes:$seconds';
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The lifecycle of the search for the current query.
enum SearchStatus { idle, loading, success, error }

/// Debounced search over a [SearchFetcher], exposed as a [ChangeNotifier].
class SearchModel extends ChangeNotifier {
  factory SearchModel({
    required SearchFetcher fetcher,
    Duration debounce = const Duration(milliseconds: 300),
  }) => SearchModel._(fetcher, debounce);

  SearchModel._(this._fetcher, this._debounce);

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;
  bool _disposed = false;

  /// Identifies the newest fetch; responses carrying an older id are stale.
  int _requestId = 0;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => List<String>.unmodifiable(_results);

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) return;

    _query = text;
    _timer?.cancel();
    _timer = null;
    // Any response still in flight belongs to an older query now.
    _requestId++;

    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    notifyListeners();
    _timer = Timer(_debounce, () {
      _timer = null;
      _start(text);
    });
  }

  Future<void> _start(String text) async {
    if (_disposed) return;

    final id = ++_requestId;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    try {
      final fetched = await _fetcher(text);
      if (_disposed || id != _requestId) return;
      _status = SearchStatus.success;
      _results = List<String>.of(fetched);
      _error = null;
    } catch (e) {
      if (_disposed || id != _requestId) return;
      _status = SearchStatus.error;
      _results = const <String>[];
      _error = e;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

/// User preferences that can be serialised to and from JSON.
class Settings {
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
  });

  /// Display name of the user. Never empty.
  final String username;

  /// Editor font size, always within [minFontSize]..[maxFontSize].
  final int fontSize;

  /// Whether the dark colour scheme is active.
  final bool darkMode;

  /// Free-form labels. Individual tags are never empty.
  final List<String> tags;

  /// Smallest accepted value for [fontSize].
  static const int minFontSize = 8;

  /// Largest accepted value for [fontSize].
  static const int maxFontSize = 72;

  /// The JSON representation understood by [parseSettings].
  Map<String, Object?> toJson() {
    return <String, Object?>{
      'username': username,
      'fontSize': fontSize,
      'darkMode': darkMode,
      'tags': List<String>.of(tags),
    };
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    if (other is! Settings) {
      return false;
    }
    if (other.username != username ||
        other.fontSize != fontSize ||
        other.darkMode != darkMode ||
        other.tags.length != tags.length) {
      return false;
    }
    for (var i = 0; i < tags.length; i++) {
      if (other.tags[i] != tags[i]) {
        return false;
      }
    }
    return true;
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';
}

/// Thrown when a document cannot be turned into a valid [Settings].
class SettingsFormatException implements Exception {
  const SettingsFormatException(this.message);

  /// Human readable explanation naming the offending key, when there is one.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Decodes [json] into [Settings].
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if a value has the wrong type or is out of
/// range. No other exception escapes this function.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('invalid JSON: ${error.message}');
  } on Object {
    throw const SettingsFormatException('invalid JSON');
  }

  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'the top level value must be a JSON object',
    );
  }

  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('"$key" is required');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('"$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  if (!map.containsKey(key)) {
    return 14;
  }
  final value = map[key];
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double &&
      value.isFinite &&
      value == value.roundToDouble()) {
    size = value.toInt();
  } else {
    throw const SettingsFormatException('"$key" must be an integer');
  }
  if (size < Settings.minFontSize || size > Settings.maxFontSize) {
    throw const SettingsFormatException(
      '"$key" must be between ${Settings.minFontSize} and '
      '${Settings.maxFontSize}',
    );
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  if (!map.containsKey(key)) {
    return false;
  }
  final value = map[key];
  if (value is! bool) {
    throw const SettingsFormatException('"$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  if (!map.containsKey(key)) {
    return const <String>[];
  }
  final value = map[key];
  if (value is! List) {
    throw const SettingsFormatException('"$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException('"$key" must only contain strings');
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException(
        '"$key" must not contain an empty string',
      );
    }
    tags.add(entry);
  }
  return List<String>.unmodifiable(tags);
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search.
enum SearchStatus { idle, loading, success, error }

/// Debounces query changes and keeps the results of the latest query only.
class SearchModel extends ChangeNotifier {
  SearchModel({
    required SearchFetcher fetcher,
    Duration debounce = const Duration(milliseconds: 300),
  }) : _searchFetcher = fetcher,
       _debounceDelay = debounce;

  final SearchFetcher _searchFetcher;
  final Duration _debounceDelay;

  Timer? _timer;

  /// Identifies the fetch that may still write to this model. Every change of
  /// the query invalidates whatever was in flight before it.
  int _fetchId = 0;
  bool _disposed = false;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;
    _fetchId++;

    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    notifyListeners();
    _timer = Timer(_debounceDelay, () {
      _timer = null;
      unawaited(_fetch(text, _fetchId));
    });
  }

  Future<void> _fetch(String text, int id) async {
    if (_disposed || id != _fetchId) {
      return;
    }
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    try {
      final List<String> fetched = await _searchFetcher(text);
      if (_disposed || id != _fetchId) {
        return;
      }
      _results = List<String>.unmodifiable(fetched);
      _error = null;
      _status = SearchStatus.success;
    } on Object catch (error) {
      if (_disposed || id != _fetchId) {
        return;
      }
      _results = const <String>[];
      _error = error;
      _status = SearchStatus.error;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    _fetchId++;
    super.dispose();
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

const Duration _tick = Duration(seconds: 1);

/// Counts down from [duration] to zero, one second at a time.
///
/// The countdown is driven by a timer that is owned by this controller and
/// cancelled when the controller is disposed. Listeners are notified on every
/// tick as well as whenever the running state changes.
class CountdownController extends ChangeNotifier {
  /// Creates a controller whose [remaining] starts at [duration].
  CountdownController({required this.duration}) : _remaining = duration;

  /// The value [remaining] starts at and is restored to by [reset].
  final Duration duration;

  Duration _remaining;
  Timer? _timer;

  /// The time left before the countdown finishes.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking.
  bool get isRunning => _timer != null;

  /// Starts ticking.
  ///
  /// Does nothing while already running or when [remaining] is already zero.
  void start() {
    if (isRunning || _remaining <= Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, (_) => _onTick());
    notifyListeners();
  }

  /// Stops ticking, keeping [remaining] where it is.
  ///
  /// Does nothing when not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _cancel();
    notifyListeners();
  }

  /// Stops ticking and restores [remaining] to [duration].
  void reset() {
    _cancel();
    _remaining = duration;
    notifyListeners();
  }

  void _onTick() {
    _remaining = _remaining - _tick;
    if (_remaining <= Duration.zero) {
      _remaining = Duration.zero;
      _cancel();
    }
    notifyListeners();
  }

  void _cancel() {
    _timer?.cancel();
    _timer = null;
  }

  @override
  void dispose() {
    _cancel();
    super.dispose();
  }
}

/// Displays the [controller]'s remaining time as `mm:ss` with start, pause and
/// reset buttons.
///
/// The controller is owned by the caller: this widget never disposes it, and
/// the same controller can be handed to another [CountdownTimer] afterwards.
class CountdownTimer extends StatefulWidget {
  /// Creates a countdown display driven by [controller].
  const CountdownTimer({required this.controller, super.key, this.onFinished});

  /// The countdown to display and control.
  final CountdownController controller;

  /// Called once each time the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  late bool _finished;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining <= Duration.zero;
    widget.controller.addListener(_handleChange);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleChange);
      _finished = widget.controller.remaining <= Duration.zero;
      widget.controller.addListener(_handleChange);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleChange);
    super.dispose();
  }

  void _handleChange() {
    setState(() {});
    if (widget.controller.remaining > Duration.zero) {
      _finished = false;
      return;
    }
    if (!_finished) {
      _finished = true;
      widget.onFinished?.call();
    }
  }

  static String _format(Duration remaining) {
    final String minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final String seconds = (remaining.inSeconds % 60).toString().padLeft(
      2,
      '0',
    );
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    final CountdownController controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(onPressed: controller.start, child: const Text('Start')),
            TextButton(onPressed: controller.pause, child: const Text('Pause')),
            TextButton(onPressed: controller.reset, child: const Text('Reset')),
          ],
        ),
      ],
    );
  }
}

import 'dart:convert';

/// The JSON keys understood by [Settings.toJson] and [parseSettings].
const String _usernameKey = 'username';
const String _fontSizeKey = 'fontSize';
const String _darkModeKey = 'darkMode';
const String _tagsKey = 'tags';

/// The value used for [Settings.fontSize] when the key is absent.
const int _defaultFontSize = 14;

/// The inclusive bounds accepted for [Settings.fontSize].
const int _minFontSize = 8;
const int _maxFontSize = 72;

/// The user preferences of the application.
class Settings {
  /// Creates a settings value.
  ///
  /// [username] must not be empty, [fontSize] must lie within `8..72` and
  /// every entry of [tags] must be a non-empty string. Values produced by
  /// [parseSettings] always satisfy those constraints.
  const Settings({
    required this.username,
    this.fontSize = _defaultFontSize,
    this.darkMode = false,
    this.tags = const <String>[],
  });

  /// The name the settings belong to. Never empty.
  final String username;

  /// The preferred font size, within `8..72`.
  final int fontSize;

  /// Whether the dark colour scheme is preferred.
  final bool darkMode;

  /// The labels attached to the account. Every entry is non-empty.
  final List<String> tags;

  /// Returns a JSON representation of these settings.
  ///
  /// `parseSettings(jsonEncode(settings.toJson()))` is equal to `settings`.
  Map<String, Object?> toJson() {
    return <String, Object?>{
      _usernameKey: username,
      _fontSizeKey: fontSize,
      _darkModeKey: darkMode,
      _tagsKey: List<String>.of(tags),
    };
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        _tagsEqual(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';
}

/// Thrown by [parseSettings] when a document cannot be read as [Settings].
///
/// The [message] names the offending key whenever the failure can be
/// attributed to one.
class SettingsFormatException implements Exception {
  /// Creates an exception describing why a document was rejected.
  const SettingsFormatException(this.message);

  /// A human readable description of the failure.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Reads [json] as a settings document.
///
/// Throws a [SettingsFormatException], and nothing else, when [json] is not
/// valid JSON, when its top level is not an object, or when a value is
/// missing, of the wrong type, or out of range. Unknown keys are ignored.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException(
      'The text is not valid JSON: ${error.message}',
    );
  }

  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'The top level of the document must be a JSON object.',
    );
  }

  return Settings(
    username: _readUsername(decoded[_usernameKey]),
    fontSize: _readFontSize(decoded[_fontSizeKey]),
    darkMode: _readDarkMode(decoded[_darkModeKey]),
    tags: _readTags(decoded[_tagsKey]),
  );
}

String _readUsername(Object? value) {
  if (value == null) {
    throw const SettingsFormatException(
      "The required key '$_usernameKey' is missing.",
    );
  }
  if (value is! String) {
    throw const SettingsFormatException(
      "The value of '$_usernameKey' must be a string.",
    );
  }
  if (value.isEmpty) {
    throw const SettingsFormatException(
      "The value of '$_usernameKey' must not be empty.",
    );
  }
  return value;
}

int _readFontSize(Object? value) {
  if (value == null) {
    return _defaultFontSize;
  }

  final int fontSize;
  if (value is int) {
    fontSize = value;
  } else if (value is double &&
      value.isFinite &&
      value.truncateToDouble() == value) {
    fontSize = value.toInt();
  } else {
    throw const SettingsFormatException(
      "The value of '$_fontSizeKey' must be an integer.",
    );
  }

  if (fontSize < _minFontSize || fontSize > _maxFontSize) {
    throw SettingsFormatException(
      "The value of '$_fontSizeKey' must be within "
      '$_minFontSize..$_maxFontSize, but was $fontSize.',
    );
  }
  return fontSize;
}

bool _readDarkMode(Object? value) {
  if (value == null) {
    return false;
  }
  if (value is! bool) {
    throw const SettingsFormatException(
      "The value of '$_darkModeKey' must be a boolean.",
    );
  }
  return value;
}

List<String> _readTags(Object? value) {
  if (value == null) {
    return const <String>[];
  }
  if (value is! List<Object?>) {
    throw const SettingsFormatException(
      "The value of '$_tagsKey' must be a list of strings.",
    );
  }

  final List<String> tags = <String>[];
  for (final Object? element in value) {
    if (element is! String) {
      throw const SettingsFormatException(
        "Every element of '$_tagsKey' must be a string.",
      );
    }
    if (element.isEmpty) {
      throw const SettingsFormatException(
        "Every element of '$_tagsKey' must not be empty.",
      );
    }
    tags.add(element);
  }
  return List<String>.unmodifiable(tags);
}

bool _tagsEqual(List<String> a, List<String> b) {
  if (identical(a, b)) {
    return true;
  }
  if (a.length != b.length) {
    return false;
  }
  for (int i = 0; i < a.length; i++) {
    if (a[i] != b[i]) {
      return false;
    }
  }
  return true;
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Counts down from [duration] to zero, one second at a time.
///
/// The object that creates the controller owns it and is responsible for
/// calling [dispose]; a [CountdownTimer] built with it never does.
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : assert(
        !duration.isNegative,
        'duration must not be negative, was $duration',
      ),
      _duration = duration,
      _remaining = duration;

  static const Duration _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// Time left before the countdown finishes. Starts at the duration the
  /// controller was created with and never goes below zero.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking down.
  bool get isRunning => _timer != null;

  /// Starts ticking. Does nothing while already running or once [remaining]
  /// has reached zero.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, (Timer timer) => _onTick());
  }

  /// Stops ticking, keeping [remaining] where it is. Does nothing when the
  /// countdown is not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _stop();
    notifyListeners();
  }

  /// Stops ticking and puts [remaining] back to the original duration.
  void reset() {
    _stop();
    _remaining = _duration;
    notifyListeners();
  }

  void _onTick() {
    final Duration next = _remaining - _tick;
    if (next <= Duration.zero) {
      _remaining = Duration.zero;
      _stop();
    } else {
      _remaining = next;
    }
    notifyListeners();
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }
}

/// Shows the remaining time of a [CountdownController] as `mm:ss` along with
/// buttons driving it.
///
/// The widget only listens to [controller]; it never disposes it, so the same
/// controller can be handed to another [CountdownTimer] afterwards.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({super.key, required this.controller, this.onFinished});

  /// The countdown this widget displays and controls.
  final CountdownController controller;

  /// Called once, when the countdown reaches zero while this widget is in the
  /// tree.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  /// Whether the current run to zero has already been reported, so that a
  /// controller sitting at zero does not fire [CountdownTimer.onFinished]
  /// again on every later notification.
  late bool _finished;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining == Duration.zero;
    widget.controller.addListener(_handleControllerChanged);
  }

  @override
  void didUpdateWidget(covariant CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleControllerChanged);
      _finished = widget.controller.remaining == Duration.zero;
      widget.controller.addListener(_handleControllerChanged);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleControllerChanged);
    super.dispose();
  }

  void _handleControllerChanged() {
    final bool reachedZero =
        !_finished && widget.controller.remaining == Duration.zero;
    _finished = widget.controller.remaining == Duration.zero;
    setState(() {});
    if (reachedZero) {
      widget.onFinished?.call();
    }
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_formatDuration(widget.controller.remaining)),
        TextButton(
          onPressed: widget.controller.start,
          child: const Text('Start'),
        ),
        TextButton(
          onPressed: widget.controller.pause,
          child: const Text('Pause'),
        ),
        TextButton(
          onPressed: widget.controller.reset,
          child: const Text('Reset'),
        ),
      ],
    );
  }
}

String _formatDuration(Duration duration) {
  final int totalSeconds = duration.inSeconds;
  final String minutes = (totalSeconds ~/ Duration.secondsPerMinute)
      .toString()
      .padLeft(2, '0');
  final String seconds = (totalSeconds % Duration.secondsPerMinute)
      .toString()
      .padLeft(2, '0');
  return '$minutes:$seconds';
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search.
enum SearchStatus { idle, loading, success, error }

/// Debounces query changes and keeps the results of the latest search.
class SearchModel extends ChangeNotifier {
  SearchModel({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;
  bool _disposed = false;

  /// Identifies the latest started fetch; responses of any other are stale.
  int _requestId = 0;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  /// The latest text passed to [onQueryChanged].
  String get query => _query;

  List<String> get results => _results;

  /// The error of the latest failed fetch, or `null`.
  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;

    if (text.isEmpty) {
      // Drop whatever is in flight for an earlier query.
      _requestId++;
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    _timer = Timer(_debounce, () {
      _timer = null;
      _startFetch(_query);
    });
    notifyListeners();
  }

  Future<void> _startFetch(String text) async {
    if (_disposed) {
      return;
    }
    final id = ++_requestId;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    List<String> fetched;
    try {
      fetched = await _fetcher(text);
    } catch (error) {
      if (_disposed || id != _requestId) {
        return;
      }
      _status = SearchStatus.error;
      _error = error;
      _results = const <String>[];
      notifyListeners();
      return;
    }

    if (_disposed || id != _requestId) {
      return;
    }
    _status = SearchStatus.success;
    _error = null;
    _results = List<String>.unmodifiable(fetched);
    notifyListeners();
  }

  @override
  void notifyListeners() {
    if (_disposed) {
      return;
    }
    super.notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

/// Thrown when a settings document cannot be parsed into a [Settings].
class SettingsFormatException implements Exception {
  /// Creates an exception describing why parsing failed.
  const SettingsFormatException(this.message);

  /// Human readable description of the problem, naming the offending key.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// User preferences for the app.
class Settings {
  /// Creates a settings value.
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
  });

  /// Name of the user the settings belong to. Must not be empty.
  final String username;

  /// Editor font size in logical pixels. Must be within `8..72`.
  final int fontSize;

  /// Whether the dark theme is selected.
  final bool darkMode;

  /// Free form labels. Every tag must be non-empty.
  final List<String> tags;

  /// Converts these settings into a JSON compatible map.
  Map<String, Object?> toJson() => <String, Object?>{
    'username': username,
    'fontSize': fontSize,
    'darkMode': darkMode,
    'tags': List<String>.of(tags),
  };

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        _tagsEqual(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';

  static bool _tagsEqual(List<String> a, List<String> b) {
    if (identical(a, b)) {
      return true;
    }
    if (a.length != b.length) {
      return false;
    }
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return false;
      }
    }
    return true;
  }
}

/// Parses [json] into a [Settings].
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if a value has the wrong type or is out of
/// range. No other exception type escapes this function.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('invalid JSON: ${error.message}');
  }

  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException('top level value must be an object');
  }

  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('missing required key "$key"');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('"$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  if (!map.containsKey(key)) {
    return 14;
  }
  final value = map[key];
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double &&
      value.isFinite &&
      value == value.roundToDouble()) {
    size = value.toInt();
  } else {
    throw const SettingsFormatException('"$key" must be an integer');
  }
  if (size < 8 || size > 72) {
    throw const SettingsFormatException('"$key" must be within 8..72');
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  if (!map.containsKey(key)) {
    return false;
  }
  final value = map[key];
  if (value is! bool) {
    throw const SettingsFormatException('"$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  if (!map.containsKey(key)) {
    return const <String>[];
  }
  final value = map[key];
  if (value is! List<Object?>) {
    throw const SettingsFormatException('"$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException('"$key" must contain only strings');
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException('"$key" entries must not be empty');
    }
    tags.add(entry);
  }
  return List<String>.unmodifiable(tags);
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the most recent search.
enum SearchStatus { idle, loading, success, error }

/// Debounces query changes and keeps the results of the latest query only.
class SearchModel extends ChangeNotifier {
  SearchModel({
    required SearchFetcher fetcher,
    Duration debounce = const Duration(milliseconds: 300),
  }) : assert(!debounce.isNegative, 'debounce must not be negative'),
       // Wrapped so that a fetcher throwing synchronously is handled the same
       // way as one completing with an error.
       _fetcher = ((String query) =>
           Future<List<String>>.sync(() => fetcher(query))),
       _debounce = debounce;

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;
  bool _disposed = false;

  /// Identifies the latest fetch; responses carrying an older id are stale.
  int _fetchId = 0;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  /// Records [text] and schedules a fetch once no further change arrives for
  /// the debounce duration.
  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;

    if (text.isEmpty) {
      // Nothing to fetch: drop whatever is in flight and start over.
      _fetchId++;
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
    } else {
      _timer = Timer(_debounce, _startFetch);
    }
    notifyListeners();
  }

  void _startFetch() {
    _timer = null;
    if (_disposed) {
      return;
    }
    final int id = ++_fetchId;
    final String query = _query;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();
    unawaited(_fetch(id, query));
  }

  Future<void> _fetch(int id, String query) {
    return _fetcher(query).then(
      (List<String> value) {
        if (_isStale(id, query)) {
          return;
        }
        _status = SearchStatus.success;
        _results = List<String>.unmodifiable(value);
        _error = null;
        notifyListeners();
      },
      onError: (Object error, StackTrace stackTrace) {
        if (_isStale(id, query)) {
          return;
        }
        _status = SearchStatus.error;
        _error = error;
        _results = const <String>[];
        notifyListeners();
      },
    );
  }

  bool _isStale(int id, String query) =>
      _disposed || id != _fetchId || query != _query;

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Counts down from [duration] to zero, one second at a time.
///
/// The object that creates a controller owns it and is responsible for
/// calling [dispose]; [CountdownTimer] never disposes the controller it is
/// given.
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  static const Duration _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// The time left before the countdown finishes.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking.
  bool get isRunning => _timer != null;

  /// Starts ticking.
  ///
  /// Does nothing while the countdown is already running or when there is no
  /// time left.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, _onTick);
  }

  /// Stops ticking, keeping [remaining] where it is.
  ///
  /// Does nothing when the countdown is not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _stop();
  }

  /// Stops ticking and sets [remaining] back to the initial duration.
  void reset() {
    _stop();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }

  void _onTick(Timer timer) {
    final Duration next = _remaining - _tick;
    if (next <= Duration.zero) {
      _remaining = Duration.zero;
      _stop();
    } else {
      _remaining = next;
    }
    notifyListeners();
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
  }
}

/// Displays the [controller]'s remaining time as `mm:ss` with start, pause and
/// reset buttons.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({super.key, required this.controller, this.onFinished});

  /// The countdown to display and drive. Owned by the caller.
  final CountdownController controller;

  /// Called once each time the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  bool _finishedReported = false;

  @override
  void initState() {
    super.initState();
    _subscribe(widget.controller);
  }

  @override
  void didUpdateWidget(covariant CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleUpdate);
      _subscribe(widget.controller);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleUpdate);
    super.dispose();
  }

  void _subscribe(CountdownController controller) {
    _finishedReported = controller.remaining == Duration.zero;
    controller.addListener(_handleUpdate);
  }

  void _handleUpdate() {
    if (!mounted) {
      return;
    }
    setState(() {});
    if (widget.controller.remaining == Duration.zero) {
      if (!_finishedReported) {
        _finishedReported = true;
        widget.onFinished?.call();
      }
    } else {
      _finishedReported = false;
    }
  }

  static String _format(Duration remaining) {
    final String minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final String seconds = (remaining.inSeconds % Duration.secondsPerMinute)
        .toString()
        .padLeft(2, '0');
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    final CountdownController controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(onPressed: controller.start, child: const Text('Start')),
            TextButton(onPressed: controller.pause, child: const Text('Pause')),
            TextButton(onPressed: controller.reset, child: const Text('Reset')),
          ],
        ),
      ],
    );
  }
}

import 'dart:convert';

import 'package:flutter/foundation.dart';

/// The smallest font size a valid [Settings] may carry.
const int _minFontSize = 8;

/// The largest font size a valid [Settings] may carry.
const int _maxFontSize = 72;

const String _usernameKey = 'username';
const String _fontSizeKey = 'fontSize';
const String _darkModeKey = 'darkMode';
const String _tagsKey = 'tags';

/// The user preferences of the app, as stored in a JSON document.
@immutable
class Settings {
  /// Creates settings for [username].
  ///
  /// [username] must not be empty and [fontSize] must be within
  /// [_minFontSize]..[_maxFontSize]; every entry of [tags] must be non-empty.
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const <String>[],
  }) : assert(username != '', 'username must not be empty'),
       assert(
         fontSize >= _minFontSize && fontSize <= _maxFontSize,
         'fontSize must be within $_minFontSize..$_maxFontSize',
       );

  /// The name the settings belong to. Never empty.
  final String username;

  /// The editor font size, within [_minFontSize]..[_maxFontSize].
  final int fontSize;

  /// Whether the dark theme is selected.
  final bool darkMode;

  /// The labels attached to these settings. Every entry is non-empty.
  final List<String> tags;

  /// Returns a JSON encodable representation of these settings.
  ///
  /// `parseSettings(jsonEncode(settings.toJson()))` equals `settings`.
  Map<String, Object?> toJson() => <String, Object?>{
    _usernameKey: username,
    _fontSizeKey: fontSize,
    _darkModeKey: darkMode,
    _tagsKey: List<String>.of(tags),
  };

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Settings &&
          other.username == username &&
          other.fontSize == fontSize &&
          other.darkMode == darkMode &&
          listEquals(other.tags, tags);

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';
}

/// Thrown by [parseSettings] when a document is not a valid [Settings].
///
/// The [message] names the offending key whenever the failure can be
/// attributed to one.
class SettingsFormatException implements Exception {
  /// Creates an exception described by [message].
  const SettingsFormatException(this.message);

  /// A human readable description of why parsing failed.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Parses [json], a JSON document holding a settings object.
///
/// Unknown keys are ignored. Throws a [SettingsFormatException] — and nothing
/// else — when the text is not JSON, when its top level is not an object, or
/// when a key is missing, of the wrong type, or out of range.
Settings parseSettings(String json) {
  final Object? decoded = _decode(json);
  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'the top level of the document must be a JSON object',
    );
  }
  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
  );
}

Object? _decode(String json) {
  try {
    return jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException(
      'the text is not valid JSON: ${error.message}',
    );
  }
}

String _readUsername(Map<String, Object?> json) {
  final Object? value = json[_usernameKey];
  if (value == null) {
    throw const SettingsFormatException('"$_usernameKey" is required');
  }
  if (value is! String) {
    throw const SettingsFormatException('"$_usernameKey" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('"$_usernameKey" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> json) {
  if (!json.containsKey(_fontSizeKey)) {
    return 14;
  }
  final Object? value = json[_fontSizeKey];
  final int fontSize;
  if (value is int) {
    fontSize = value;
  } else if (value is double) {
    if (!value.isFinite || value != value.truncateToDouble()) {
      throw const SettingsFormatException(
        '"$_fontSizeKey" must be a whole number',
      );
    }
    fontSize = value.toInt();
  } else {
    throw const SettingsFormatException('"$_fontSizeKey" must be an integer');
  }
  if (fontSize < _minFontSize || fontSize > _maxFontSize) {
    throw const SettingsFormatException(
      '"$_fontSizeKey" must be within $_minFontSize..$_maxFontSize',
    );
  }
  return fontSize;
}

bool _readDarkMode(Map<String, Object?> json) {
  if (!json.containsKey(_darkModeKey)) {
    return false;
  }
  final Object? value = json[_darkModeKey];
  if (value is! bool) {
    throw const SettingsFormatException('"$_darkModeKey" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> json) {
  if (!json.containsKey(_tagsKey)) {
    return const <String>[];
  }
  final Object? value = json[_tagsKey];
  if (value is! List<Object?>) {
    throw const SettingsFormatException(
      '"$_tagsKey" must be a list of strings',
    );
  }
  final List<String> tags = <String>[];
  for (final Object? element in value) {
    if (element is! String) {
      throw const SettingsFormatException(
        '"$_tagsKey" must contain only strings',
      );
    }
    if (element.isEmpty) {
      throw const SettingsFormatException(
        '"$_tagsKey" must not contain an empty string',
      );
    }
    tags.add(element);
  }
  return List<String>.unmodifiable(tags);
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Counts down from a fixed duration to zero, one second at a time.
///
/// The object that creates the controller owns it and is responsible for
/// calling [dispose]; widgets that render it never do.
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : assert(duration >= Duration.zero, 'duration must not be negative'),
      _duration = duration,
      _remaining = duration;

  static const Duration _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// Time left before the countdown finishes. Starts at the duration the
  /// controller was created with and never goes below [Duration.zero].
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking.
  bool get isRunning => _timer != null;

  /// Starts ticking. Does nothing while already running or once [remaining]
  /// has reached zero.
  void start() {
    if (_timer != null || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, _onTick);
  }

  /// Stops ticking, keeping [remaining] where it is. Does nothing when the
  /// countdown is not running.
  void pause() {
    final timer = _timer;
    if (timer == null) {
      return;
    }
    timer.cancel();
    _timer = null;
    notifyListeners();
  }

  /// Stops ticking and puts [remaining] back to the initial duration.
  void reset() {
    _timer?.cancel();
    _timer = null;
    _remaining = _duration;
    notifyListeners();
  }

  void _onTick(Timer timer) {
    final next = _remaining - _tick;
    _remaining = next > Duration.zero ? next : Duration.zero;
    if (_remaining == Duration.zero) {
      timer.cancel();
      _timer = null;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

/// Shows the remaining time of a [CountdownController] as `mm:ss` along with
/// start, pause and reset buttons.
///
/// The widget does not own [controller]: it neither disposes it nor prevents
/// it from being handed to another [CountdownTimer] later.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({super.key, required this.controller, this.onFinished});

  /// The countdown to display and drive.
  final CountdownController controller;

  /// Called once each time the countdown reaches zero while this widget is
  /// listening.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  late Duration _remaining;

  @override
  void initState() {
    super.initState();
    _remaining = widget.controller.remaining;
    widget.controller.addListener(_handleChange);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleChange);
      _remaining = widget.controller.remaining;
      widget.controller.addListener(_handleChange);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleChange);
    super.dispose();
  }

  void _handleChange() {
    final previous = _remaining;
    setState(() {
      _remaining = widget.controller.remaining;
    });
    if (previous > Duration.zero && _remaining == Duration.zero) {
      widget.onFinished?.call();
    }
  }

  String _format(Duration remaining) {
    final minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final seconds = (remaining.inSeconds % Duration.secondsPerMinute)
        .toString()
        .padLeft(2, '0');
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    final controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(_remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(onPressed: controller.start, child: const Text('Start')),
            TextButton(onPressed: controller.pause, child: const Text('Pause')),
            TextButton(onPressed: controller.reset, child: const Text('Reset')),
          ],
        ),
      ],
    );
  }
}

import 'dart:async';
import 'dart:collection';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search.
enum SearchStatus { idle, loading, success, error }

/// Debounces query changes and exposes the state of the resulting search.
class SearchModel extends ChangeNotifier {
  /// Creates a model that calls [fetcher] once [debounce] has passed without
  /// another query change.
  SearchModel({
    required SearchFetcher fetcher,
    Duration debounce = const Duration(milliseconds: 300),
  }) {
    // Assigned in the body because named parameters cannot be private, so
    // these fields cannot be initializing formals.
    _fetcher = fetcher;
    _debounce = debounce;
  }

  late final SearchFetcher _fetcher;
  late final Duration _debounce;

  Timer? _timer;
  bool _disposed = false;

  /// Identifies the newest accepted query; responses stamped with an older id
  /// are stale and dropped.
  int _requestId = 0;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  /// The state of the latest search.
  SearchStatus get status => _status;

  /// The latest text passed to [onQueryChanged].
  String get query => _query;

  /// The results of the latest successful fetch.
  List<String> get results => UnmodifiableListView<String>(_results);

  /// The error of the latest failed fetch, or `null`.
  Object? get error => _error;

  /// Stores [text] and schedules a fetch for it.
  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }

    _timer?.cancel();
    _timer = null;
    _requestId++;
    _query = text;

    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    notifyListeners();
    final int requestId = _requestId;
    _timer = Timer(_debounce, () {
      _timer = null;
      unawaited(_fetch(text, requestId));
    });
  }

  Future<void> _fetch(String text, int requestId) async {
    if (_disposed || requestId != _requestId) {
      return;
    }

    _status = SearchStatus.loading;
    notifyListeners();

    try {
      final List<String> fetched = await _fetcher(text);
      if (_disposed || requestId != _requestId) {
        return;
      }
      _results = List<String>.unmodifiable(fetched);
      _error = null;
      _status = SearchStatus.success;
    } catch (error) {
      if (_disposed || requestId != _requestId) {
        return;
      }
      _results = const <String>[];
      _error = error;
      _status = SearchStatus.error;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

/// Smallest accepted value for [Settings.fontSize].
const int _minFontSize = 8;

/// Largest accepted value for [Settings.fontSize].
const int _maxFontSize = 72;

/// User preferences that can be stored as, and restored from, JSON.
class Settings {
  /// Creates a settings snapshot.
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
  });

  /// Name of the user owning these settings. Never empty.
  final String username;

  /// Editor font size, always within 8..72 inclusive.
  final int fontSize;

  /// Whether the dark colour scheme is preferred.
  final bool darkMode;

  /// Free-form labels attached to the user. No tag is empty.
  final List<String> tags;

  /// Returns a JSON-encodable representation of these settings.
  Map<String, Object?> toJson() => <String, Object?>{
    'username': username,
    'fontSize': fontSize,
    'darkMode': darkMode,
    'tags': List<String>.of(tags),
  };

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        _tagsEqual(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';

  static bool _tagsEqual(List<String> a, List<String> b) {
    if (identical(a, b)) {
      return true;
    }
    if (a.length != b.length) {
      return false;
    }
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return false;
      }
    }
    return true;
  }
}

/// Thrown when a JSON document cannot be read as a [Settings] value.
class SettingsFormatException implements Exception {
  /// Creates an exception describing why parsing failed.
  const SettingsFormatException(this.message);

  /// Human readable description of the problem. Mentions the offending key
  /// when the failure can be attributed to one.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Parses [json] into a [Settings] value.
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if any known key holds a value of the wrong
/// type or outside its allowed range. No other exception type escapes.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on Object {
    throw const SettingsFormatException('the text is not valid JSON');
  }
  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'the top level of the document is not a JSON object',
    );
  }
  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('"$key" is required but missing');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('"$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('"$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  if (!map.containsKey(key)) {
    return 14;
  }
  final value = map[key];
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double &&
      value.isFinite &&
      value == value.roundToDouble()) {
    size = value.toInt();
  } else {
    throw const SettingsFormatException('"$key" must be an integer');
  }
  if (size < _minFontSize || size > _maxFontSize) {
    throw const SettingsFormatException(
      '"$key" must be within $_minFontSize..$_maxFontSize',
    );
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  if (!map.containsKey(key)) {
    return false;
  }
  final value = map[key];
  if (value is! bool) {
    throw const SettingsFormatException('"$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  if (!map.containsKey(key)) {
    return const [];
  }
  final value = map[key];
  if (value is! List<Object?>) {
    throw const SettingsFormatException('"$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException('"$key" must contain only strings');
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException('"$key" must not contain empty tags');
    }
    tags.add(entry);
  }
  return tags;
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search a [SearchModel] cares about.
enum SearchStatus { idle, loading, success, error }

/// Debounced search state: the newest query always wins, and results that
/// belong to an older query are discarded whenever they arrive.
class SearchModel extends ChangeNotifier {
  SearchModel({
    required SearchFetcher fetcher,
    Duration debounce = const Duration(milliseconds: 300),
  }) : this._(fetcher, debounce);

  SearchModel._(this._fetcher, this._debounce);

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;

  /// Identifies the fetch whose result is still wanted. Bumping it makes every
  /// fetch started earlier stale.
  int _generation = 0;
  bool _disposed = false;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = List<String>.unmodifiable(const <String>[]);
  Object? _error;

  SearchStatus get status => _status;

  String get query => _query;

  List<String> get results => _results;

  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;
    // Anything already in flight belongs to an older query now.
    _generation++;

    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = List<String>.unmodifiable(const <String>[]);
      _error = null;
    } else {
      _timer = Timer(_debounce, () => unawaited(_fetch(text)));
    }
    notifyListeners();
  }

  Future<void> _fetch(String text) async {
    if (_disposed) {
      return;
    }
    _timer = null;
    final int generation = ++_generation;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    List<String> data;
    try {
      data = await _fetcher(text);
    } on Object catch (error) {
      if (_disposed || generation != _generation) {
        return;
      }
      _status = SearchStatus.error;
      _results = List<String>.unmodifiable(const <String>[]);
      _error = error;
      notifyListeners();
      return;
    }

    if (_disposed || generation != _generation) {
      return;
    }
    _status = SearchStatus.success;
    _results = List<String>.unmodifiable(data);
    _error = null;
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    // Drop whatever is still in flight.
    _generation++;
    super.dispose();
  }
}

import 'dart:convert';

/// Thrown when a settings document cannot be turned into a [Settings].
///
/// The [message] always mentions the offending key, when there is one, so a
/// caller can point a user straight at the part of the document to fix.
class SettingsFormatException implements Exception {
  /// Creates an exception described by [message].
  const SettingsFormatException(this.message);

  /// A human readable description of what is wrong with the document.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// The user preferences of the app.
class Settings {
  /// Creates a set of preferences.
  ///
  /// [username] must not be empty, [fontSize] must be within 8..72 and every
  /// entry of [tags] must be non-empty.
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const <String>[],
  }) : assert(username != '', 'username must not be empty'),
       assert(
         fontSize >= _minFontSize && fontSize <= _maxFontSize,
         'fontSize must be within $_minFontSize..$_maxFontSize',
       );

  static const int _defaultFontSize = 14;
  static const int _minFontSize = 8;
  static const int _maxFontSize = 72;

  static const String _usernameKey = 'username';
  static const String _fontSizeKey = 'fontSize';
  static const String _darkModeKey = 'darkMode';
  static const String _tagsKey = 'tags';

  /// The name the user goes by. Never empty.
  final String username;

  /// The size of the app's body text, within 8..72.
  final int fontSize;

  /// Whether the dark colour scheme is used.
  final bool darkMode;

  /// The labels the user has picked. Every entry is non-empty.
  final List<String> tags;

  /// Returns a JSON encodable representation of these settings.
  ///
  /// Feeding the encoded form back to [parseSettings] yields an equal object.
  Map<String, Object?> toJson() => <String, Object?>{
    _usernameKey: username,
    _fontSizeKey: fontSize,
    _darkModeKey: darkMode,
    _tagsKey: List<String>.of(tags),
  };

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        _tagsEqual(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';

  static bool _tagsEqual(List<String> a, List<String> b) {
    if (identical(a, b)) {
      return true;
    }
    if (a.length != b.length) {
      return false;
    }
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return false;
      }
    }
    return true;
  }
}

/// Parses [json] into a [Settings].
///
/// The document must be a JSON object holding `username` and, optionally,
/// `fontSize`, `darkMode` and `tags`; any other key is ignored. Anything the
/// rules above reject — malformed text, a top level that is not an object, a
/// missing `username`, a value of the wrong type or one outside its range —
/// throws a [SettingsFormatException] and nothing else.
Settings parseSettings(String json) {
  final Object? document = _decode(json);
  if (document is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'The top level of the document must be a JSON object.',
    );
  }

  final String username = _readString(document, Settings._usernameKey);
  if (username.isEmpty) {
    throw const SettingsFormatException(
      'Key "${Settings._usernameKey}" must not be empty.',
    );
  }

  final int fontSize = _readInt(
    document,
    Settings._fontSizeKey,
    orElse: Settings._defaultFontSize,
  );
  if (fontSize < Settings._minFontSize || fontSize > Settings._maxFontSize) {
    throw SettingsFormatException(
      'Key "${Settings._fontSizeKey}" must be within '
      '${Settings._minFontSize}..${Settings._maxFontSize}, was $fontSize.',
    );
  }

  return Settings(
    username: username,
    fontSize: fontSize,
    darkMode: _readBool(document, Settings._darkModeKey, orElse: false),
    tags: _readTags(document, Settings._tagsKey),
  );
}

Object? _decode(String json) {
  try {
    return jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException(
      'The document is not valid JSON: '
      '${error.message}',
    );
  }
}

/// Returns the value stored under [key], or `null` when the key is absent.
///
/// A key holding an explicit `null` is reported as a wrong type rather than as
/// an absent key, so both forms are told apart by the callers.
Object? _lookUp(Map<String, Object?> document, String key) {
  if (!document.containsKey(key)) {
    return null;
  }
  final Object? value = document[key];
  if (value == null) {
    throw SettingsFormatException('Key "$key" must not be null.');
  }
  return value;
}

String _readString(Map<String, Object?> document, String key) {
  final Object? value = _lookUp(document, key);
  if (value == null) {
    throw SettingsFormatException('Key "$key" is required but missing.');
  }
  if (value is! String) {
    throw SettingsFormatException('Key "$key" must be a string.');
  }
  return value;
}

int _readInt(Map<String, Object?> document, String key, {required int orElse}) {
  final Object? value = _lookUp(document, key);
  if (value == null) {
    return orElse;
  }
  if (value is int) {
    return value;
  }
  if (value is double && value.isFinite && value == value.roundToDouble()) {
    return value.toInt();
  }
  throw SettingsFormatException('Key "$key" must be a whole number.');
}

bool _readBool(
  Map<String, Object?> document,
  String key, {
  required bool orElse,
}) {
  final Object? value = _lookUp(document, key);
  if (value == null) {
    return orElse;
  }
  if (value is! bool) {
    throw SettingsFormatException('Key "$key" must be a boolean.');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> document, String key) {
  final Object? value = _lookUp(document, key);
  if (value == null) {
    return const <String>[];
  }
  if (value is! List<Object?>) {
    throw SettingsFormatException('Key "$key" must be a list of strings.');
  }
  final tags = <String>[];
  for (final Object? entry in value) {
    if (entry is! String) {
      throw SettingsFormatException('Key "$key" must only hold strings.');
    }
    if (entry.isEmpty) {
      throw SettingsFormatException('Key "$key" must not hold an empty tag.');
    }
    tags.add(entry);
  }
  return tags;
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Drives a countdown from [duration] down to zero, one second at a time.
///
/// The object that creates the controller owns it and is responsible for
/// calling [dispose].
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : _duration = duration,
      _remaining = duration;

  static const Duration _tickInterval = Duration(seconds: 1);

  final Duration _duration;
  Duration _remaining;
  Timer? _timer;

  /// Time left before the countdown finishes. Starts at the duration the
  /// controller was created with.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking.
  bool get isRunning => _timer != null;

  /// Starts ticking. Does nothing while already running or once [remaining]
  /// has reached zero.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tickInterval, _tick);
    notifyListeners();
  }

  /// Stops ticking, keeping [remaining] where it is. Does nothing when the
  /// countdown is not running.
  void pause() {
    if (!isRunning) {
      return;
    }
    _stop();
    notifyListeners();
  }

  /// Stops ticking and sets [remaining] back to the initial duration.
  void reset() {
    _stop();
    _remaining = _duration;
    notifyListeners();
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }

  void _tick(Timer timer) {
    final Duration next = _remaining - _tickInterval;
    _remaining = next > Duration.zero ? next : Duration.zero;
    if (_remaining == Duration.zero) {
      _stop();
    }
    notifyListeners();
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
  }
}

/// Shows the [controller]'s remaining time as `mm:ss` along with start, pause
/// and reset buttons.
///
/// The widget never disposes the [controller]; the caller keeps ownership and
/// may hand the same controller to another [CountdownTimer] later.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({super.key, required this.controller, this.onFinished});

  final CountdownController controller;

  /// Called once when the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  bool _finished = false;

  @override
  void initState() {
    super.initState();
    _finished = widget.controller.remaining == Duration.zero;
    widget.controller.addListener(_handleControllerChanged);
  }

  @override
  void didUpdateWidget(CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_handleControllerChanged);
      _finished = widget.controller.remaining == Duration.zero;
      widget.controller.addListener(_handleControllerChanged);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_handleControllerChanged);
    super.dispose();
  }

  void _handleControllerChanged() {
    if (!mounted) {
      return;
    }
    setState(() {});
    final bool atZero = widget.controller.remaining == Duration.zero;
    if (atZero && !_finished) {
      _finished = true;
      widget.onFinished?.call();
    } else if (!atZero) {
      _finished = false;
    }
  }

  static String _format(Duration remaining) {
    final String minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final String seconds = (remaining.inSeconds % 60).toString().padLeft(
      2,
      '0',
    );
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(widget.controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(
              onPressed: widget.controller.start,
              child: const Text('Start'),
            ),
            TextButton(
              onPressed: widget.controller.pause,
              child: const Text('Pause'),
            ),
            TextButton(
              onPressed: widget.controller.reset,
              child: const Text('Reset'),
            ),
          ],
        ),
      ],
    );
  }
}

import 'dart:async';

import 'package:flutter/material.dart';

/// Counts down from [duration] to zero, one second at a time.
///
/// The countdown is driven by a periodic timer that only exists while the
/// controller is running. Whoever creates the controller owns it and is
/// responsible for calling [dispose].
class CountdownController extends ChangeNotifier {
  CountdownController({required Duration duration})
    : assert(
        duration >= Duration.zero,
        'duration must not be negative, was $duration',
      ),
      _duration = duration,
      _remaining = duration;

  static const Duration _tick = Duration(seconds: 1);

  final Duration _duration;

  Duration _remaining;
  Timer? _timer;

  /// Time left before the countdown reaches zero.
  Duration get remaining => _remaining;

  /// Whether the countdown is currently ticking down.
  bool get isRunning => _timer != null;

  /// Starts ticking. Does nothing while already running or at zero.
  void start() {
    if (isRunning || _remaining == Duration.zero) {
      return;
    }
    _timer = Timer.periodic(_tick, (_) => _onTick());
    notifyListeners();
  }

  /// Stops ticking without changing [remaining]. Does nothing when stopped.
  void pause() {
    if (!isRunning) {
      return;
    }
    _stop();
    notifyListeners();
  }

  /// Stops ticking and puts [remaining] back to the original duration.
  void reset() {
    _stop();
    _remaining = _duration;
    notifyListeners();
  }

  void _onTick() {
    final Duration next = _remaining - _tick;
    _remaining = next > Duration.zero ? next : Duration.zero;
    if (_remaining == Duration.zero) {
      _stop();
    }
    notifyListeners();
  }

  void _stop() {
    _timer?.cancel();
    _timer = null;
  }

  @override
  void dispose() {
    _stop();
    super.dispose();
  }
}

/// Shows the [controller]'s remaining time as `mm:ss` with start, pause and
/// reset buttons.
///
/// The widget listens to the controller but never disposes it, so the same
/// controller can outlive this widget and be handed to another one.
class CountdownTimer extends StatefulWidget {
  const CountdownTimer({required this.controller, super.key, this.onFinished});

  /// The countdown this widget displays and drives.
  final CountdownController controller;

  /// Called once each time the countdown reaches zero.
  final VoidCallback? onFinished;

  @override
  State<CountdownTimer> createState() => _CountdownTimerState();
}

class _CountdownTimerState extends State<CountdownTimer> {
  late bool _wasFinished;

  @override
  void initState() {
    super.initState();
    _wasFinished = widget.controller.remaining == Duration.zero;
    widget.controller.addListener(_onControllerChanged);
  }

  @override
  void didUpdateWidget(covariant CountdownTimer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.controller != widget.controller) {
      oldWidget.controller.removeListener(_onControllerChanged);
      _wasFinished = widget.controller.remaining == Duration.zero;
      widget.controller.addListener(_onControllerChanged);
    }
  }

  @override
  void dispose() {
    widget.controller.removeListener(_onControllerChanged);
    super.dispose();
  }

  void _onControllerChanged() {
    if (!mounted) {
      return;
    }
    setState(() {});
    final bool isFinished = widget.controller.remaining == Duration.zero;
    if (isFinished && !_wasFinished) {
      widget.onFinished?.call();
    }
    _wasFinished = isFinished;
  }

  static String _format(Duration remaining) {
    final String minutes = remaining.inMinutes.toString().padLeft(2, '0');
    final String seconds = (remaining.inSeconds % Duration.secondsPerMinute)
        .toString()
        .padLeft(2, '0');
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    final CountdownController controller = widget.controller;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: <Widget>[
        Text(_format(controller.remaining)),
        Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            TextButton(onPressed: controller.start, child: const Text('Start')),
            TextButton(onPressed: controller.pause, child: const Text('Pause')),
            TextButton(onPressed: controller.reset, child: const Text('Reset')),
          ],
        ),
      ],
    );
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the latest search.
enum SearchStatus { idle, loading, success, error }

/// Debounced search state holder.
///
/// Text changes are stored immediately, but a fetch only starts once the
/// debounce duration has elapsed without another change. Responses that no
/// longer match the current query are dropped, so stale results can never
/// overwrite newer ones.
class SearchModel extends ChangeNotifier {
  SearchModel({
    required this._fetcher,
    this._debounce = const Duration(milliseconds: 300),
  });

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;

  /// Incremented whenever the query changes or the model is disposed, so that
  /// in-flight fetches started for an older value can be identified and
  /// discarded.
  int _generation = 0;
  bool _disposed = false;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  SearchStatus get status => _status;

  /// The latest text passed to [onQueryChanged].
  String get query => _query;

  /// The results of the latest successful fetch. Unmodifiable.
  List<String> get results => _results;

  /// The error of the latest failed fetch, or `null`.
  Object? get error => _error;

  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;
    _generation++;

    if (text.isEmpty) {
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    notifyListeners();
    final generation = _generation;
    _timer = Timer(_debounce, () => _fetch(text, generation));
  }

  Future<void> _fetch(String text, int generation) async {
    if (_disposed || generation != _generation) {
      return;
    }
    _timer = null;
    _status = SearchStatus.loading;
    _error = null;
    notifyListeners();

    try {
      final values = await _fetcher(text);
      if (_disposed || generation != _generation) {
        return;
      }
      _results = List<String>.unmodifiable(values);
      _status = SearchStatus.success;
      _error = null;
    } catch (error) {
      if (_disposed || generation != _generation) {
        return;
      }
      _results = const <String>[];
      _error = error;
      _status = SearchStatus.error;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _generation++;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';

/// Fetches the results for [query].
typedef SearchFetcher = Future<List<String>> Function(String query);

/// The state of the most recent search.
enum SearchStatus { idle, loading, success, error }

/// Runs a [SearchFetcher] over the typed query, debounced, and exposes the
/// state of the search to listeners.
///
/// Only the fetch for the query that is still current can change the state:
/// responses that arrive for an outdated query are dropped, whatever the
/// order in which the fetches complete.
class SearchModel extends ChangeNotifier {
  /// Creates a model that searches with [fetcher] once [debounce] has passed
  /// without a further change.
  SearchModel({
    required SearchFetcher fetcher,
    Duration debounce = const Duration(milliseconds: 300),
  }) : this._(fetcher, debounce);

  SearchModel._(this._fetcher, this._debounce);

  final SearchFetcher _fetcher;
  final Duration _debounce;

  Timer? _timer;

  /// Identifies the fetch whose result is still wanted. Bumping it drops
  /// whatever is in flight.
  int _requestId = 0;

  bool _disposed = false;

  SearchStatus _status = SearchStatus.idle;
  String _query = '';
  List<String> _results = const <String>[];
  Object? _error;

  /// The state of the latest search.
  SearchStatus get status => _status;

  /// The latest text passed to [onQueryChanged].
  String get query => _query;

  /// The results of the latest successful fetch, unmodifiable.
  List<String> get results => _results;

  /// The error of the latest failed fetch, or `null`.
  Object? get error => _error;

  /// Records [text] as the current query and schedules a fetch for it.
  ///
  /// Text equal to the current query changes nothing; an empty query resets
  /// the model to [SearchStatus.idle] without fetching.
  void onQueryChanged(String text) {
    if (_disposed || text == _query) {
      return;
    }
    _query = text;
    _timer?.cancel();
    _timer = null;

    if (text.isEmpty) {
      _requestId++;
      _status = SearchStatus.idle;
      _results = const <String>[];
      _error = null;
      notifyListeners();
      return;
    }

    notifyListeners();
    _timer = Timer(_debounce, () {
      _timer = null;
      unawaited(_fetch(text));
    });
  }

  Future<void> _fetch(String text) async {
    if (_disposed) {
      return;
    }
    final int id = ++_requestId;
    _status = SearchStatus.loading;
    notifyListeners();

    try {
      final List<String> fetched = await _fetcher(text);
      if (_disposed || id != _requestId) {
        return;
      }
      _results = List<String>.unmodifiable(fetched);
      _error = null;
      _status = SearchStatus.success;
    } on Object catch (error) {
      if (_disposed || id != _requestId) {
        return;
      }
      _error = error;
      _results = const <String>[];
      _status = SearchStatus.error;
    }
    notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _timer?.cancel();
    _timer = null;
    super.dispose();
  }
}

import 'dart:convert';

/// User-facing configuration that can be serialised to and from JSON.
class Settings {
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
  });

  /// The account name. Never empty.
  final String username;

  /// The editor font size, always within [minFontSize] .. [maxFontSize].
  final int fontSize;

  /// Whether the dark colour scheme is selected.
  final bool darkMode;

  /// Free-form labels. Never contains an empty entry.
  final List<String> tags;

  /// Smallest accepted value for [fontSize].
  static const int minFontSize = 8;

  /// Largest accepted value for [fontSize].
  static const int maxFontSize = 72;

  /// The JSON representation understood by [parseSettings].
  Map<String, Object?> toJson() {
    return <String, Object?>{
      'username': username,
      'fontSize': fontSize,
      'darkMode': darkMode,
      'tags': List<String>.of(tags),
    };
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        _tagsEqual(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';

  static bool _tagsEqual(List<String> a, List<String> b) {
    if (identical(a, b)) {
      return true;
    }
    if (a.length != b.length) {
      return false;
    }
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return false;
      }
    }
    return true;
  }
}

/// Thrown when a JSON document cannot be turned into a [Settings].
class SettingsFormatException implements Exception {
  const SettingsFormatException(this.message);

  /// Human readable description of the problem.
  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

/// Parses [json] into a [Settings].
///
/// Throws a [SettingsFormatException] if the text is not a JSON object, if a
/// required key is missing, or if a value has the wrong type or is out of
/// range. No other exception type escapes this function.
Settings parseSettings(String json) {
  final Object? decoded;
  try {
    decoded = jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException('not valid JSON: ${error.message}');
  }

  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException('top level value is not a JSON object');
  }

  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
  );
}

String _readUsername(Map<String, Object?> map) {
  const key = 'username';
  if (!map.containsKey(key)) {
    throw const SettingsFormatException('missing required key "$key"');
  }
  final value = map[key];
  if (value is! String) {
    throw const SettingsFormatException('key "$key" must be a string');
  }
  if (value.isEmpty) {
    throw const SettingsFormatException('key "$key" must not be empty');
  }
  return value;
}

int _readFontSize(Map<String, Object?> map) {
  const key = 'fontSize';
  if (!map.containsKey(key)) {
    return 14;
  }
  final value = map[key];
  final int size;
  if (value is int) {
    size = value;
  } else if (value is double) {
    if (!value.isFinite || value != value.roundToDouble()) {
      throw const SettingsFormatException('key "$key" must be an integer');
    }
    size = value.toInt();
  } else {
    throw const SettingsFormatException('key "$key" must be an integer');
  }
  if (size < Settings.minFontSize || size > Settings.maxFontSize) {
    throw const SettingsFormatException(
      'key "$key" must be between ${Settings.minFontSize} '
      'and ${Settings.maxFontSize}',
    );
  }
  return size;
}

bool _readDarkMode(Map<String, Object?> map) {
  const key = 'darkMode';
  if (!map.containsKey(key)) {
    return false;
  }
  final value = map[key];
  if (value is! bool) {
    throw const SettingsFormatException('key "$key" must be a boolean');
  }
  return value;
}

List<String> _readTags(Map<String, Object?> map) {
  const key = 'tags';
  if (!map.containsKey(key)) {
    return const <String>[];
  }
  final value = map[key];
  if (value is! List<Object?>) {
    throw const SettingsFormatException('key "$key" must be a list of strings');
  }
  final tags = <String>[];
  for (final entry in value) {
    if (entry is! String) {
      throw const SettingsFormatException(
        'key "$key" must contain only strings',
      );
    }
    if (entry.isEmpty) {
      throw const SettingsFormatException(
        'key "$key" must not contain empty strings',
      );
    }
    tags.add(entry);
  }
  return List<String>.unmodifiable(tags);
}

import 'dart:convert';

/// User preferences for the app.
///
/// The invariants documented on each field are enforced by [parseSettings];
/// values built in code are trusted.
class Settings {
  const Settings({
    required this.username,
    this.fontSize = 14,
    this.darkMode = false,
    this.tags = const [],
  });

  /// The account name. Never empty.
  final String username;

  /// The editor font size, between [minFontSize] and [maxFontSize] inclusive.
  final int fontSize;

  /// Whether the dark theme is selected.
  final bool darkMode;

  /// Free-form labels. Never contains an empty tag.
  final List<String> tags;

  /// The smallest accepted [fontSize].
  static const int minFontSize = 8;

  /// The largest accepted [fontSize].
  static const int maxFontSize = 72;

  /// A JSON representation that [parseSettings] reads back into an equal value.
  Map<String, Object?> toJson() {
    return <String, Object?>{
      _usernameKey: username,
      _fontSizeKey: fontSize,
      _darkModeKey: darkMode,
      _tagsKey: List<String>.of(tags),
    };
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) {
      return true;
    }
    return other is Settings &&
        other.username == username &&
        other.fontSize == fontSize &&
        other.darkMode == darkMode &&
        _tagsEqual(other.tags, tags);
  }

  @override
  int get hashCode =>
      Object.hash(username, fontSize, darkMode, Object.hashAll(tags));

  @override
  String toString() =>
      'Settings(username: $username, fontSize: $fontSize, '
      'darkMode: $darkMode, tags: $tags)';
}

/// Thrown by [parseSettings] when a document cannot be read as [Settings].
///
/// The [message] names the offending key whenever one can be identified.
class SettingsFormatException implements Exception {
  const SettingsFormatException(this.message);

  final String message;

  @override
  String toString() => 'SettingsFormatException: $message';
}

const String _usernameKey = 'username';
const String _fontSizeKey = 'fontSize';
const String _darkModeKey = 'darkMode';
const String _tagsKey = 'tags';

/// Reads a [Settings] value from a JSON document.
///
/// Throws a [SettingsFormatException] — and nothing else — when [json] is not
/// valid JSON, when its top level is not an object, or when a key is missing,
/// has the wrong type, or falls outside its accepted range. Keys other than
/// `username`, `fontSize`, `darkMode` and `tags` are ignored.
Settings parseSettings(String json) {
  final Object? decoded = _decode(json);
  if (decoded is! Map<String, Object?>) {
    throw const SettingsFormatException(
      'The top level of the document must be a JSON object.',
    );
  }
  return Settings(
    username: _readUsername(decoded),
    fontSize: _readFontSize(decoded),
    darkMode: _readDarkMode(decoded),
    tags: _readTags(decoded),
  );
}

Object? _decode(String json) {
  try {
    return jsonDecode(json);
  } on FormatException catch (error) {
    throw SettingsFormatException(
      'The document is not valid JSON: '
      '${error.message}',
    );
  }
}

String _readUsername(Map<String, Object?> json) {
  final Object? value = json[_usernameKey];
  if (value == null) {
    throw const SettingsFormatException(
      'The required key "$_usernameKey" is missing.',
    );
  }
  if (value is! String) {
    throw const SettingsFormatException(
      'The key "$_usernameKey" must hold a string.',
    );
  }
  if (value.isEmpty) {
    throw const SettingsFormatException(
      'The key "$_usernameKey" must not be empty.',
    );
  }
  return value;
}

int _readFontSize(Map<String, Object?> json) {
  if (!json.containsKey(_fontSizeKey)) {
    return 14;
  }
  final Object? value = json[_fontSizeKey];
  final int fontSize;
  if (value is int) {
    fontSize = value;
  } else if (value is double &&
      value.isFinite &&
      value == value.roundToDouble()) {
    fontSize = value.toInt();
  } else {
    throw const SettingsFormatException(
      'The key "$_fontSizeKey" must hold a whole number.',
    );
  }
  if (fontSize < Settings.minFontSize || fontSize > Settings.maxFontSize) {
    throw const SettingsFormatException(
      'The key "$_fontSizeKey" must be between ${Settings.minFontSize} and '
      '${Settings.maxFontSize}.',
    );
  }
  return fontSize;
}

bool _readDarkMode(Map<String, Object?> json) {
  if (!json.containsKey(_darkModeKey)) {
    return false;
  }
  final Object? value = json[_darkModeKey];
  if (value is! bool) {
    throw const SettingsFormatException(
      'The key "$_darkModeKey" must hold a boolean.',
    );
  }
  return value;
}

List<String> _readTags(Map<String, Object?> json) {
  if (!json.containsKey(_tagsKey)) {
    return const <String>[];
  }
  final Object? value = json[_tagsKey];
  if (value is! List<Object?>) {
    throw const SettingsFormatException(
      'The key "$_tagsKey" must hold a list of strings.',
    );
  }
  final List<String> tags = <String>[];
  for (final Object? element in value) {
    if (element is! String) {
      throw const SettingsFormatException(
        'The key "$_tagsKey" must hold a list of strings.',
      );
    }
    if (element.isEmpty) {
      throw const SettingsFormatException(
        'The key "$_tagsKey" must not contain an empty tag.',
      );
    }
    tags.add(element);
  }
  return List<String>.unmodifiable(tags);
}

bool _tagsEqual(List<String> a, List<String> b) {
  if (identical(a, b)) {
    return true;
  }
  if (a.length != b.length) {
    return false;
  }
  for (int i = 0; i < a.length; i++) {
    if (a[i] != b[i]) {
      return false;
    }
  }
  return true;
}
